/**
 * Tests for {@link Nysiis}, the NYSIIS phonetic encoder.
 *
 * <p>The encoder first cleans the input (keeping only letters, upper-casing them)
 * and then applies the NYSIIS algorithm. In strict mode (the default) the result
 * is truncated to a maximum length of 6 characters; in non-strict mode the full
 * code is returned.</p>
 */
@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class Nysiis_ESTest extends Nysiis_ESTest_scaffolding {

  /**
   * In non-strict mode the encoded value is not truncated, so the full
   * 8-character NYSIIS code is returned.
   */
  @Test(timeout = 4000)
  public void nysiis_nonStrictMode_returnsUntruncatedCode()  throws Throwable  {
      Nysiis nonStrictEncoder = new Nysiis(false);

      String code = nonStrictEncoder.nysiis("&:ZN(sDK;@X'DhCe");

      assertEquals("ZNSDCXDC", code);
  }

  /**
   * The same input as above but with the default (strict) encoder, whose
   * output is capped at 6 characters.
   */
  @Test(timeout = 4000)
  public void nysiis_strictMode_truncatesCodeToSixChars()  throws Throwable  {
      Nysiis strictEncoder = new Nysiis();

      String code = strictEncoder.nysiis("&:ZN(sDK;@X'DhCe");

      assertEquals("ZNSDCX", code);
  }

  /**
   * Encoding a value via the generic {@code encode(Object)} method does not
   * change the encoder's configured strict mode.
   */
  @Test(timeout = 4000)
  public void encode_doesNotAffectStrictMode()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      encoder.encode("A");

      assertTrue(encoder.isStrict());
  }

  /**
   * An empty input is encoded without altering the encoder's strict mode.
   */
  @Test(timeout = 4000)
  public void nysiis_emptyInput_keepsStrictMode()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      encoder.nysiis("");

      assertTrue(encoder.isStrict());
  }

  /**
   * A {@code null} input is handled gracefully and the encoder remains strict.
   */
  @Test(timeout = 4000)
  public void nysiis_nullInput_keepsStrictMode()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      encoder.nysiis((String) null);

      assertTrue(encoder.isStrict());
  }

  /**
   * {@code encode(Object)} rejects arguments that are not Strings by throwing
   * an exception originating from {@link Nysiis}.
   */
  @Test(timeout = 4000)
  public void encodeObject_nonStringArgument_throwsException()  throws Throwable  {
      Nysiis encoder = new Nysiis();
      Object nonStringArgument = new Object();

      try {
        encoder.encode(nonStringArgument);
        fail("Expecting exception: Exception");
      } catch(Exception e) {
         //
         // Parameter supplied to Nysiis encode is not of type java.lang.String
         //
         verifyException("org.apache.commons.codec.language.Nysiis", e);
      }
  }

  /**
   * {@code encode(Object)} accepts a String argument and returns its NYSIIS code.
   */
  @Test(timeout = 4000)
  public void encodeObject_stringArgument_returnsCode()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      Object code = encoder.encode((Object) "org.apache.commons.codec.EncodeyException");

      assertEquals("ORGAPA", code);
      assertNotNull(code);
  }

  /**
   * Punctuation and digits are stripped before encoding, leaving only the
   * letters to drive the NYSIIS code.
   */
  @Test(timeout = 4000)
  public void nysiis_inputWithSymbols_encodesLettersOnly()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.nysiis("B*(EG$;*A+w7oQ");

      assertEquals("BAGAG", code);
      assertTrue(encoder.isStrict());
  }

  /**
   * Mixed-case input with embedded symbols is upper-cased and cleaned before
   * being encoded.
   */
  @Test(timeout = 4000)
  public void nysiis_mixedCaseInput_encodesCleanedLetters()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.nysiis("|5tl0=0cuh:63pEY");

      assertTrue(encoder.isStrict());
      assertEquals("TLCAPY", code);
  }

  /**
   * A longer mixed-case input is truncated to 6 characters in strict mode.
   */
  @Test(timeout = 4000)
  public void nysiis_longMixedCaseInput_truncatesToSixChars()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.nysiis("dIpYze0FuZfr/K1EPh%");

      assertEquals("DAPYSA", code);
  }

  /**
   * The {@code encode(String)} method produces the same NYSIIS code as
   * {@link Nysiis#nysiis(String)}; the "KSCH" prefix collapses to a single "C".
   */
  @Test(timeout = 4000)
  public void encodeString_returnsNysiisCode()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.encode("kSCH");

      assertNotNull(code);
      assertTrue(encoder.isStrict());
      assertEquals("C", code);
  }

  /**
   * Input containing braces and other symbols is cleaned to its letters and
   * encoded to a 6-character code.
   */
  @Test(timeout = 4000)
  public void nysiis_inputWithBraces_encodesCleanedLetters()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.nysiis("Bd}F:LH6ciJkN{]w^1");

      assertEquals("BDFLCA", code);
      assertNotNull(code);
  }

  /**
   * Another mixed-case input with symbols encodes to a 6-character code.
   */
  @Test(timeout = 4000)
  public void nysiis_anotherMixedCaseInput_encodesCleanedLetters()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.nysiis("tl1[CoH5>Aeu)UA;J.");

      assertEquals("TLCAHA", code);
      assertNotNull(code);
  }

  /**
