  @Test(timeout = 4000)
  public void encodeString_inputWithSpacesAndSymbols_encodesCleanedLetters()  throws Throwable  {
      Nysiis encoder = new Nysiis();

      String code = encoder.encode("@A9Q mhK(EVj%r");

      assertEquals("AGNCAF", code);
  }
